struct P { x: i32 }
fn read(p: &P) -> i32 { return p.x; }
fn bump(p: &mut P) -> i32 { p.x = p.x + 1; return p.x; }
fn main() -> i32 { let mut p = P { x: 1 }; return bump(&mut p) - 2; }
